{"command":"python - << 'PY'
import copy, random, time, hashlib
from reference import Task
N=20000
INSTANCES=30
seeds=random.SystemRandom().sample(range(10**9),INSTANCES)
size=N*1024

t_ref=t_hashlib=0
for seed in seeds:
    problem=Task().generate_problem(N,seed)
    p=copy.deepcopy(problem);
    t=time.perf_counter(); Task().solve(p); t_ref+=time.perf_counter()-t
    p=copy.deepcopy(problem);
    t=time.perf_counter();
    hashlib.sha256(p['plaintext']).digest();
    t_hashlib+=time.perf_counter()-t
print('ref',t_ref,'hashlib',t_hashlib,'speedup',t_ref/t_hashlib)
PY"}

