import random, time, threading, hashlib, os
size=20_480_000
p=random.randbytes(size)

NTHREADS=4
chunks=[p[i*size//NTHREADS:(i+1)*size//NTHREADS] for i in range(NTHREADS)]

digests=[None]*NTHREADS
def worker(i):
    digests[i]=hashlib.sha256(chunks[i]).digest()

start=time.perf_counter();
threads=[threading.Thread(target=worker,args=(i,)) for i in range(NTHREADS)]
for t in threads: t.start()
for t in threads: t.join()
print('multi-thread', time.perf_counter()-start)

start=time.perf_counter(); hashlib.sha256(p).digest(); print('single', time.perf_counter()-start)
